import type { Locale } from "@/lib/i18n";

export type LandmarkContent = {
  name: string;
  duration: string;
  audio: string;
  description: string;
  story: string;
  facts: readonly { label: string; value: string }[];
};

type AddedLocale = Exclude<Locale, "en" | "de" | "fr" | "ar">;
type FactTuple = readonly [label: string, value: string];

function landmark(
  name: string,
  duration: string,
  description: string,
  story: string,
  facts: readonly FactTuple[],
): LandmarkContent {
  return {
    name,
    duration,
    audio: "",
    description,
    story,
    facts: facts.map(([label, value]) => ({ label, value })),
  };
}

